PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT ?vehicleType (COUNT(DISTINCT ?c) AS ?collisionCount) ?totalCollisions ?evidence WHERE {
  # collisions that involve a vulnerable road user
  ?c a :VRUCollision ;
     :hasVehicle ?v .
  ?v :vehicleType ?vehicleType .
  # evidence list of collision IDs
  BIND(STRAFTER(STR(?c),"resource/") AS ?collisionId)

  # sub‑select to get the overall number of VRU collisions
  { SELECT (COUNT(DISTINCT ?cAll) AS ?totalCollisions) WHERE { ?cAll a :VRUCollision } }

  # collect evidence IDs per row (all collisions of this vehicle type)
  {
    SELECT (GROUP_CONCAT(DISTINCT ?collisionId; separator=",") AS ?evidence) WHERE {
      ?c2 a :VRUCollision ; :hasVehicle ?v2 .
      ?v2 :vehicleType ?vehicleType .
      BIND(STRAFTER(STR(?c2),"resource/") AS ?collisionId)
    }
  }
}
GROUP BY ?vehicleType ?totalCollisions ?evidence
ORDER BY DESC(?collisionCount)
LIMIT 500

PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT ?localAuthorityName (COUNT(DISTINCT ?c) AS ?collisionCount) ?total WHERE {
  ?c a :KSICollision ;
     :roadClass "A" ;
     :surfaceCondition ?surf ;
     :occurredIn ?lsoa .
  FILTER(?surf IN ("Wet or damp", "Frost or ice"))
  ?lsoa :partOf ?la .
  ?la a :LocalAuthority ;
      :areaName ?localAuthorityName .
  {
    SELECT (COUNT(DISTINCT ?cAll) AS ?total) WHERE {
      ?cAll a :KSICollision ;
            :roadClass "A" ;
            :surfaceCondition ?sAll ;
            :occurredIn ?lsoaAll .
      FILTER(?sAll IN ("Wet or damp", "Frost or ice"))
    }
  }
}
GROUP BY ?localAuthorityName ?total
ORDER BY DESC(?collisionCount)
LIMIT 5

