PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT ?lsoa ?areaCode ?policeForce ?pfName (COUNT(DISTINCT ?c) AS ?n) ?total (GROUP_CONCAT(DISTINCT STRAFTER(STR(?c),"resource/" ); separator=",") AS ?evidence)
WHERE {
  ?lsoa a :HighRiskArea ;
        :areaCode ?areaCode ;
        :partOf ?policeForce .
  ?policeForce a :PoliceForce ;
                :areaName ?pfName .
  ?c a :KSICollision ;
     :occurredIn ?lsoa .
  {
    SELECT (COUNT(DISTINCT ?cAll) AS ?total)
    WHERE { ?cAll a :KSICollision }
  }
}
GROUP BY ?lsoa ?areaCode ?policeForce ?pfName ?total
ORDER BY DESC(?n)
LIMIT 500

PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT ?vehicleManoeuvre ?lightCondition (COUNT(DISTINCT ?c) AS ?count) ?total (GROUP_CONCAT(DISTINCT STRAFTER(STR(?c),"resource/" ); separator=",") AS ?evidence)
WHERE {
  ?c a :Collision ;
     :hasVehicle ?v ;
     :involvesCasualty ?cas .
  ?v :vehicleManoeuvre ?vehicleManoeuvre .
  ?cas a :Pedestrian ;
       :casualtySeverity ?severity .
  FILTER(?severity IN ("Fatal","Serious"))
  ?c :lightCondition ?lightCondition .
  FILTER(?lightCondition IN ("Daylight","Darkness - lights lit","Darkness - no lighting","Darkness - lights unlit","Darkness - lighting unknown"))
  { SELECT (COUNT(DISTINCT ?c2) AS ?total) WHERE { ?c2 a :Collision } }
}
GROUP BY ?vehicleManoeuvre ?lightCondition ?total
ORDER BY DESC(?count)
LIMIT 500

PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT ?policeForceName ?lightCondition (COUNT(DISTINCT ?c) AS ?collisionCount) ?evidence WHERE {
  ?c a :KSICollision ;
     :lightCondition ?lightCondition ;
     :occurredIn ?lsoa .
  ?lsoa :partOf ?pf .
  ?pf a :PoliceForce ;
      :areaName ?policeForceName .
  FILTER(?lightCondition IN ("Daylight", "Darkness - lights lit", "Darkness - no lighting", "Darkness - lights unlit", "Darkness - lighting unknown"))
  BIND(STRAFTER(STR(?c),"resource/") AS ?collisionId)
  BIND(?collisionId AS ?evidence)
}
GROUP BY ?policeForceName ?lightCondition
ORDER BY ?policeForceName ?lightCondition
LIMIT 500

PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT ?casualtyClass (COUNT(DISTINCT ?cas) AS ?count) (GROUP_CONCAT(DISTINCT STRAFTER(STR(?c),"resource/" ); separator=",") AS ?evidence)
WHERE {
  ?c a :KSICollision ;
     :hasVehicle ?v .
  ?v :hasCasualty ?cas .
  ?cas :casualtyAgeBand ?ageBand ;
       :casualtySeverity ?sev ;
       :casualtyClass ?casualtyClass .
  FILTER(?ageBand >= 0 && ?ageBand <= 15)
  FILTER(?sev IN ("Fatal","Serious"))
}
GROUP BY ?casualtyClass
ORDER BY DESC(?count)
LIMIT 500

PREFIX : <https://crash.example.org/ontology#>
PREFIX res: <https://crash.example.org/resource/>
SELECT (COUNT(DISTINCT ?c) AS ?collisionCount) (MAX(?speed) AS ?fastestSpeed) ?evidence WHERE {
  ?c a :Collision ;
     :speedLimit ?speed ;
     :hasVehicle ?v .
  FILTER(?speed >= 50)
  ?v :hasCasualty ?cas .
  ?cas a :Motorcyclist ;
       :casualtySeverity ?sev .
  FILTER(?sev IN ("Fatal", "Serious"))
  BIND(STRAFTER(STR(?c),"resource/") AS ?cID)
  BIND(?cID AS ?collision)
  # evidence list of collision IDs
  {
    SELECT (GROUP_CONCAT(DISTINCT ?cID; separator=",") AS ?evidence) WHERE {
      ?c a :Collision ; :speedLimit ?speed ; :hasVehicle ?v .
      FILTER(?speed >= 50)
      ?v :hasCasualty ?cas .
      ?cas a :Motorcyclist ; :casualtySeverity ?sev .
      FILTER(?sev IN ("Fatal", "Serious"))
      BIND(STRAFTER(STR(?c),"resource/") AS ?cID)
    }
  }
}
GROUP BY ?evidence
LIMIT 500
